const now = Date.now();
const ts = (minutesAgo) => new Date(now - minutesAgo * 60_000).toISOString();
const txn = (id, account, type, amount, minutesAgo, status = 'COMPLETED', stage = 'POSTED', channel = 'WEB', card = null, currency = 'USD') => ({
  TRANSACTION_ID: id, ACCOUNT_ID: account, CARD_ID: card, TRANSACTION_TYPE: type,
  TRANSACTION_STAGE: stage, TRANSACTION_STATUS: status, TRANSACTION_AMOUNT: String(amount),
  CURRENCY: currency, TRANSACTION_TIMESTAMP: ts(minutesAgo), CHANNEL: channel,
  COUNTERPARTY_REFERENCE: `DEMO-${id}`, RELATED_TRANSACTION_ID: null
});

